#!/usr/bin/env bash
# phase-330 W7.e — no committed SystemModels, ever.
#
# The resolved model is a BUILD ARTIFACT (`<ws>/build/nros/models/…`,
# regenerated by `nros sync` from launch + system.toml). A tracked copy
# re-opens the issue-0380 class: hand-edits typed into an artifact that the
# next regeneration silently deletes. Four such incidents preceded the ban.
#
# If a dim or param can only be expressed by editing a model, that is a
# resolver-input schema gap — extend system.toml (phase-330 W1 pattern),
# never commit the artifact.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
tracked="$(git ls-files '*_model.yaml' '*/system_model.yaml')"
if [ -n "$tracked" ]; then
    echo "check-no-tracked-models: committed SystemModel(s) found — the model is a build artifact (phase-330 W4.a/W7):" >&2
    printf '%s\n' "$tracked" | sed 's/^/  /' >&2
    echo "  Author the data in system.toml and re-run \`nros sync\`; never track the model." >&2
    exit 1
fi
echo "check-no-tracked-models OK."
